#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1 << 19 | 5;
int total_numbers, exponent, modulus, max_bit, count[MAX_SIZE], f_array[MAX_SIZE];
int tmp1_arr[20][MAX_SIZE], tmp2_arr[20][MAX_SIZE], tmp3_arr[20][MAX_SIZE];
long long power_product;
long long t_arr[20][MAX_SIZE];
long long factorial[MAX_SIZE], inv_factorial[MAX_SIZE];

long long fastExponentiation(long long base, long long exp) {
    long long result = 1, current = base;
    while (exp) {
        if (exp & 1) result = result * current % modulus;
        current = current * current % modulus;
        exp >>= 1;
    }
    return result;
}

void initialize() {
    factorial[0] = 1;
    for (int i = 1; i <= max_bit; i++)
        factorial[i] = factorial[i - 1] * i % modulus;
    inv_factorial[max_bit] = fastExponentiation(factorial[max_bit], modulus - 2);
    for (int i = max_bit - 1; i >= 0; i--)
        inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % modulus;
}

int get_lower_power(int x) {
    int power = 1;
    while (power < x) power <<= 1;
    return power;
}

void transformFWT(int *array, int length, bool inverse = false) {
    long long *temp = t_arr[0];
    for (int i = 0; i < length; i++) temp[i] = array[i];
    if (inverse)
        for (int i = 1; i < length; i <<= 1)
            for (int j = 0; j < length; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] -= temp[k];
    else
        for (int i = 1; i < length; i <<= 1)
            for (int j = 0; j < length; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] += temp[k];
    for (int i = 0; i < length; i++) {
        array[i] = temp[i] % modulus;
        if (array[i] < 0) array[i] += modulus;
    }
}

inline void adjust_mod(long long &x) { x >= power_product ? x -= power_product : x; }

void multiply() {
    for (int j = 0; j <= 19; j++) {
        memset(tmp1_arr[j], 0, sizeof(int[max_bit + 1]));
        memset(t_arr[j], 0, sizeof(long long[max_bit + 1]));
    }
    for (int j = 0; j <= max_bit; j++)
        tmp1_arr[count[j]][j] = f_array[j];
    for (int j = 0; j <= 19; j++)
        transformFWT(tmp1_arr[j], max_bit + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                adjust_mod(t_arr[q + l][s] += 1LL * tmp1_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp3_arr[q][s] = t_arr[q][s] % modulus;
    for (int j = 0; j <= 19; j++)
        transformFWT(tmp3_arr[j], max_bit + 1, true);
    for (int j = 0; j <= max_bit; j++)
        f_array[j] = tmp3_arr[count[j]][j];
}

void multiplySecond() {
    static int tmp[20][MAX_SIZE];
    for (int i = 0; i <= 19; i++)
        memset(t_arr[i], 0, sizeof(long long[max_bit + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                adjust_mod(t_arr[q + l][s] += 1LL * tmp2_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp[q][s] = t_arr[q][s] % modulus;
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp[i], max_bit + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2_arr[i], 0, sizeof(int[max_bit + 1]));
    for (int i = 0; i <= max_bit; i++)
        tmp2_arr[count[i]][i] = tmp[count[i]][i];
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp2_arr[i], max_bit + 1);
}

int main() {
    scanf("%d%d%d", &total_numbers, &exponent, &modulus);
    power_product = 1LL * modulus * modulus;
    if (total_numbers & 1) {
        printf("%lld", fastExponentiation(exponent, total_numbers));
        return 0;
    }
    f_array[0] = 1;
    max_bit = get_lower_power(total_numbers + 1) - 1;
    initialize();
    for (int i = 0; i <= max_bit; i++)
        count[i] = __builtin_popcount(i);
    for (int i = 0; i <= max_bit; i++)
        tmp2_arr[count[i]][i] = inv_factorial[i];
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp2_arr[i], max_bit + 1);
    int res_exponent = exponent;
    while (exponent) {
        if (exponent & 1) multiply();
        exponent >>= 1;
        if (exponent) multiplySecond();
    }
    printf("%lld", (fastExponentiation(res_exponent, total_numbers) - factorial[total_numbers] * f_array[total_numbers] % modulus + modulus) % modulus);
    return 0;
}
